package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)

	scanner.Scan() // read and ignore first token
	scanner.Scan()
	str := scanner.Text()

	if strings.Contains(str, "CC") || strings.Contains(str, "YY") || strings.Contains(str, "MM") {
		fmt.Println("No")
		return
	}

	if strings.HasPrefix(str, "?") || strings.HasSuffix(str, "?") ||
		strings.Contains(str, "??") || strings.Contains(str, "C?C") ||
		strings.Contains(str, "Y?Y") || strings.Contains(str, "M?M") {
		fmt.Println("Yes")
	} else {
		fmt.Println("No")
	}
}

